export const groupThemes = {
    green: {
      bar: "bg-money",
      iconBg: "bg-mint",
      iconText: "text-money",
      swatch: "bg-[#dcefe6]",
    },
    amber: {
      bar: "bg-amber-600",
      iconBg: "bg-sand",
      iconText: "text-amber-700",
      swatch: "bg-[#fdf0c4]",
    },
    rose: {
      bar: "bg-rose",
      iconBg: "bg-rose/10",
      iconText: "text-rose",
      swatch: "bg-[#f3ddd8]",
    },
    violet: {
      bar: "bg-violet-500",
      iconBg: "bg-violet-100",
      iconText: "text-violet-600",
      swatch: "bg-[#e6e2f3]",
    },
    sky: {
      bar: "bg-sky-500",
      iconBg: "bg-sky-100",
      iconText: "text-sky-600",
      swatch: "bg-[#dde9f0]",
    },
  };

  export const memberColors = [
    "bg-violet-400",
    "bg-amber-300",
    "bg-emerald-300",
    "bg-violet-300",
    "bg-pink-300",
  ];

  export const initialGroups = [
    {
      id: 1,
      name: "Navrangpura flat",
      meta: "Hostel • 4 people",
      balance: 864,
      theme: "green",
      members: ["KS", "RP", "DM", "HJ"],
    },
    {
      id: 2,
      name: "Vadodara trip",
      meta: "College trip • 5 people",
      balance: -427.5,
      theme: "amber",
      members: ["KS", "ND", "RP", "DM", "+1"],
    },
    {
      id: 3,
      name: "CE friends",
      meta: "Classmates • 6 people",
      balance: 182,
      theme: "rose",
      members: ["KS", "RP", "ND"],
    },
  ];

  export function formatBalance(amount) {
    const sign = amount > 0 ? "+" : amount < 0 ? "-" : "";
    const value = Math.abs(amount).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    return `${sign}₹${value}`;
  }
